ALTER TABLE inbox_settings ADD COLUMN signature_enabled boolean NOT NULL DEFAULT false,ADD COLUMN signature_template text NOT NULL DEFAULT '— {{agent.name}}',ADD COLUMN human_session_minutes int NOT NULL DEFAULT 0 CHECK(human_session_minutes BETWEEN 0 AND 10080),ADD COLUMN delivery_error_tag text NOT NULL DEFAULT '',ADD COLUMN sla_escalation_enabled boolean NOT NULL DEFAULT false,ADD COLUMN escalation_user_id uuid REFERENCES users(id);
ALTER TABLE conversations ADD COLUMN human_since timestamptz,ADD COLUMN sla_escalated_at timestamptz;
ALTER TABLE refresh_tokens ADD COLUMN device_label text NOT NULL DEFAULT '',ADD COLUMN last_seen_at timestamptz;
CREATE FUNCTION track_human_session() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.handled_by='human' AND(OLD.handled_by<>'human' OR NEW.assigned_to IS DISTINCT FROM OLD.assigned_to) THEN NEW.human_since=now();ELSIF NEW.handled_by='bot' THEN NEW.human_since=NULL;END IF;RETURN NEW;END $$;
CREATE TRIGGER track_human_session BEFORE UPDATE OF handled_by,assigned_to ON conversations FOR EACH ROW EXECUTE FUNCTION track_human_session();
CREATE FUNCTION inbox_policy_due(p_limit int) RETURNS TABLE(id uuid,tenant_id uuid) LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT cv.id,cv.tenant_id FROM conversations cv JOIN inbox_settings s ON s.tenant_id=cv.tenant_id LEFT JOIN departments d ON d.id=cv.department_id WHERE cv.status<>'closed' AND ((cv.handled_by='human' AND s.human_session_minutes>0 AND cv.human_since<now()-make_interval(mins=>s.human_session_minutes)) OR(cv.handled_by='human' AND s.sla_escalation_enabled AND d.sla_minutes>0 AND cv.last_inbound_at<now()-make_interval(mins=>d.sla_minutes) AND(cv.sla_escalated_at IS NULL OR cv.sla_escalated_at<cv.last_inbound_at) AND NOT EXISTS(SELECT 1 FROM messages m WHERE m.conversation_id=cv.id AND m.sender_type='agent' AND NOT m.is_internal AND m.created_at>=cv.last_inbound_at))) ORDER BY cv.last_message_at LIMIT LEAST(p_limit,100) $$;
REVOKE ALL ON FUNCTION inbox_policy_due(int) FROM PUBLIC;GRANT EXECUTE ON FUNCTION inbox_policy_due(int) TO app_user;
